    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", v):
        return False
    try:
        datetime.datetime.strptime(v, "%Y-%m-%d")
        return True
    except ValueError:
        return False

def is_number(v):
    try:
        float(v)
        return True
    except (ValueError, TypeError):
        return False

def is_int(v):
    return bool(re.fullmatch(r"-?\d+", v))

email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[a-z]{2,}$")

violations = []
def add(table, row, column, rule):
    violations.append({"table": table, "row": row, "column": column, "rule": rule})

# ---- load ----
cust_h, cust = load("customers.csv")
ord_h, orders = load("orders.csv")
oi_h, order_items = load("order_items.csv")
prod_h, products = load("products.csv")
ref_h, refunds = load("refunds.csv")
ship_h, shipments = load("shipments.csv")

def col(header, name):
    return header.index(name)

# ---- customers ----
c_id = col(cust_h, "id"); c_email = col(cust_h, "email")
c_date = col(cust_h, "signup_date"); c_tier = col(cust_h, "tier")
seen = set()
for i, r in enumerate(cust, start=1):
    # not_null all columns
    for name, idx in [("id", c_id), ("email", c_email), ("signup_date", c_date), ("tier", c_tier)]:
        if r[idx].strip() == "":
            add("customers", i, name, "not_null")
    if r[c_id].strip() != "":
        if r[c_id] in seen:
            add("customers", i, "id", "id")
        else:
            seen.add(r[c_id])
    if r[c_email].strip() != "" and not email_re.fullmatch(r[c_email]):
        add("customers", i, "email", "email")
    if r[c_date].strip() != "" and not is_valid_date(r[c_date]):
        add("customers", i, "signup_date", "date")
    if r[c_tier].strip() != "" and r[c_tier] not in ("free", "pro", "enterprise"):
        add("customers", i, "tier", "enum")

# ---- products ----
p_sku = col(prod_h, "sku"); p_name = col(prod_h, "name")
p_price = col(prod_h, "price"); p_cat = col(prod_h, "category")
seen_sku = set()
for i, r in enumerate(products, start=1):
    for name, idx in [("sku", p_sku), ("name", p_name), ("price", p_price), ("category", p_cat)]:
        if r[idx].strip() == "":
            add("products", i, name, "not_null")
    if r[p_sku].strip() != "":
        if r[p_sku] in seen_sku:
            add("products", i, "sku", "sku")
        else:
            seen_sku.add(r[p_sku])
    if r[p_price].strip() != "":
        if not is_number(r[p_price]):
            add("products", i, "price", "range")
        elif not (float(r[p_price]) > 0):
            add("products", i, "price", "range")

# ---- orders ----
o_id = col(ord_h, "id"); o_cid = col(ord_h, "customer_id")
o_date = col(ord_h, "order_date"); o_status = col(ord_h, "status"); o_total = col(ord_h, "total")

