        add("orders", i, "customer_id", "foreign_key")
    if r[o_date].strip() != "" and not is_valid_date(r[o_date]):
        add("orders", i, "order_date", "date")
    if r[o_status].strip() != "" and r[o_status] not in ("placed", "paid", "shipped", "cancelled"):
        add("orders", i, "status", "enum")
    if r[o_total].strip() != "":
        if not is_number(r[o_total]):
            add("orders", i, "total", "range")
        elif not (float(r[o_total]) >= 0):
            add("orders", i, "total", "range")

# ---- order_items ----
